-- Day 21: Project: Recruitment Analytics - Setup Script
-- 30 Day SQL Challenge | Stephen | Data

DROP TABLE IF EXISTS fact_applications, bridge_job_skill, dim_candidate, dim_skill, dim_job CASCADE;
DROP TABLE IF EXISTS applications, candidates, job_skills, jobs, skills, departments CASCADE;
DROP TABLE IF EXISTS raw_applications, raw_job_postings, raw_skills CASCADE;

-- =====================================================================
-- RAW: skills taxonomy reference (name -> category)
-- =====================================================================
CREATE TABLE raw_skills (
    skill_name     VARCHAR(40) NOT NULL,
    skill_category VARCHAR(30) NOT NULL
);

-- =====================================================================
-- RAW: job postings. required_skills is a semicolon cell (1NF violation);
-- cost_centre repeats with department (the 3NF transitive dependency).
-- Rows 1-14 are the verified teaching slice (SQL is in 12 of 14).
-- =====================================================================
CREATE TABLE raw_job_postings (
    job_id            INTEGER PRIMARY KEY,
    title             VARCHAR(60) NOT NULL,
    department        VARCHAR(40) NOT NULL,
    cost_centre       VARCHAR(20) NOT NULL,   -- depends on department, not the job
    location          VARCHAR(40) NOT NULL,
    seniority         VARCHAR(20) NOT NULL,
    posted_date       DATE        NOT NULL,
    salary_budget_min INTEGER     NOT NULL,
    salary_budget_max INTEGER     NOT NULL,
    required_skills   VARCHAR(200) NOT NULL   -- <<< the multi-valued cell
);

-- =====================================================================
-- RAW: application events. Candidate details are denormalised inline and
-- repeat across a candidate's applications (extracted into candidates at 3NF).
-- offer_salary is populated on Hired only; days_to_decision is derived downstream.
-- =====================================================================
CREATE TABLE raw_applications (
    application_id  INTEGER PRIMARY KEY,
    job_id          INTEGER NOT NULL,
    candidate_name  VARCHAR(60) NOT NULL,
    candidate_email VARCHAR(80),                 -- some rows arrive null (dirty extract)
    source_channel  VARCHAR(20) NOT NULL,
    applied_date    DATE        NOT NULL,
    decided_date    DATE,                    -- NULL = still in pipeline
    outcome         VARCHAR(20) NOT NULL,    -- Hired / Rejected / Offer Declined / In Progress
    offer_salary    INTEGER                  -- populated on Hired only
);
